namespace EmployeeManagement.API.DTOs
{
    /// <summary>
    /// Represents the employee information returned by the API.
    ///
    /// This class defines the structure of the JSON response
    /// that the client receives when employee data is requested.
    ///
    /// EmployeeService maps the Employee database entity
    /// to this DTO before returning the result to the controller.
    /// </summary>
    public class EmployeeResponse
    {
        // Unique identifier of the employee in the database.
        //
        // This ID is normally generated by the database when
        // a new employee is inserted.
        //
        // Example: 10
        public int Id { get; set; }

        // Employee's full name.
        //
        // Example: "Rahul Patil"
        //
        // string.Empty initializes the property with an empty string
        // instead of leaving it uninitialized.
        public string Name { get; set; } = string.Empty;

        // Employee's email address.
        //
        // Example: "rahul@example.com"
        public string Email { get; set; } = string.Empty;

        // Department in which the employee works.
        //
        // Example: "IT"
        public string Department { get; set; } = string.Empty;

        // Employee's salary.
        //
        // decimal is used to represent the salary as a decimal number.
        //
        // Example: 65000.00
        public decimal Salary { get; set; }

        // Employee's contact number.
        //
        // The ? indicates that the property can be null.
        // This allows the API to represent employees whose phone
        // number has not been provided.
        public string? PhoneNumber { get; set; }

        // Employee's joining date.
        //
        // DateTime? allows the joining date to be null.
        // This is useful when the date is not known or is missing
        // from an existing employee record.
        public DateTime? JoiningDate { get; set; }

        // Employee's job title.
        //
        // This is optional, so it can contain a string or null.
        //
        // Example: "Software Developer"
        public string? JobTitle { get; set; }
    }
}